ainpage.php">Panel</a><a class="active" href="showdoctor.php">Doktorlar</a></nav></div></header><main class="admin-wrap"><div class="page-head"><div><span class="eyebrow">DOKTOR YÖNETİMİ</span><h1>Doktorlar</h1><p>Sistemde kayıtlı doktorların güncel listesini görüntüleyin.</p></div><a class="button" href="adddoctor.php">+ Doktor Ekle</a></div><section class="card table-card"><div class="table-top"><h2>Doktor listesi</h2><span class="count"><?php echo $count;?> doktor</span></div><?php if(!$count):?><div class="empty">Kayıtlı doktor bulunmuyor.</div><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>DID</th><th>Doktor</th><th>Doğum</th><th>Deneyim</th><th>Uzmanlık</th><th>İletişim</th><th>Bölge</th></tr></thead><tbody><?php while($r=mysqli_fetch_assoc($result)):?><tr><td>#<?php echo (int)$r['DID'];?></td><td><span class="doctor-name">Dr. <?php echo htmlspecialchars($r['name']);?></span><br><span class="muted"><?php echo htmlspecialchars($r['address']);?></span></td><td><?php echo htmlspecialchars($r['dob']);?></td><td><?php echo htmlspecialchars($r['experience']);?> yıl</td><td><?php echo htmlspecialchars($r['specialization']);?></td><td><?php echo htmlspecialchars($r['contact']);?></td><td><?php echo htmlspecialchars($r['region']);?></td></tr><?php endwhile;?></tbody></table></div><div class="mobile-list"><?php mysqli_data_seek($result,0);while($r=mysqli_fetch_assoc($result)):?><article class="mobile-item"><div class="mobile-name">Dr. <?php echo htmlspecialchars($r['name']);?></div><div class="mobile-grid"><div><strong>ID</strong>#<?php echo (int)$r['DID'];?></div><div><strong>Uzmanlık</strong><?php echo htmlspecialchars($r['specialization']);?></div><div><strong>Deneyim</strong><?php echo htmlspecialchars($r['experience']);?> yıl</div><div><strong>Telefon</strong><?php echo htmlspecialchars($r['contact']);?></div></div></article><?php endwhile;?></div><?php endif;?></section></main></body></html>